 "content": "def transform(grid):
    out=[row[:] for row in grid]
    rows=[r for r,row in enumerate(grid) if 3 in row]
    cols=[c for row in grid for c,v in enumerate(row) if v==3]
    r0,r1=min(rows),max(rows); c0,c1=min(cols),max(cols)
    markers=[(r,c) for r in range(r0+1,r1) for c in range(c0+1,c1) if grid[r][c]==3]
    for r in range(r0+1,r1):
        for c in range(c0+1,c1): out[r][c]=4
    for r,c in markers: out[r][c]=3
    # Project the seed as a radius-two square outline, clipped to the frame interior.
    for mr,mc in markers:
        for r in range(r0+1,r1):
            for c in range(c0+1,c1):
                if max(abs(r-mr),abs(c-mc))==2 and grid[r][c]!=3: out[r][c]=2
    return out
